      --surface-2: #12121a;
      --border: #1e1e2d;
      --border-accent: #2d2d44;
      --text: #e4e4e7;
      --text-dim: #a1a1aa;
      --text-faint: #71717a;
      --spore: #a3e635;
      --spore-dim: #65a30d;
      --growth: #22d3ee;
      --network: #f472b6;
