      gap: 12px;
      font-family: var(--font-display);
      font-size: 16px;
      font-weight: 500;
      color: var(--text);
    }

    .nav-logo::before {
      content: '';
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--spore);
      box-shadow: 0 0 12px var(--spore);
      animation: pulse 2s ease-in-out infinite;
    }

    @keyframes pulse {
